(()=>{'use strict';const form=document.getElementById('product-form'),button=document.getElementById('pricing-calculate'),result=document.getElementById('pricing-result'),margin=document.getElementById('pricing-margin');if(!form||!button||!result||!margin)return;const costs=['materials','labour','production','packCost','delivery','other'];const instructions='Review the suggested price, then save your product. This is a costing estimate, not a customer quote.';button.onclick=()=>{let total=0;for(const key of costs){const input=form.elements[key],value=Number(input.value);if(input.value.trim()===''||!Number.isFinite(value)||value<0){result.textContent='Enter a confirmed, non-negative amount for every unit cost. Unknown costs cannot be treated as zero.';const details=form.querySelector('details');if(details)details.open=true;input.focus();return;}total+=value;}const rate=Number(margin.value);if(margin.value.trim()===''||!Number.isFinite(rate)||rate<0||rate>=100){result.textContent='Choose a target margin from 0% to below 100%.';margin.focus();return;}if(!Number.isFinite(total)||total<=0){result.textContent='Confirm a positive total unit cost before calculating a selling price.';return;}const price=Math.ceil(total/(1-rate/100)*100)/100;if(!Number.isFinite(price)){result.textContent='These amounts cannot produce a valid price. Review your costs and margin.';return;}form.elements.price.value=price.toFixed(2);result.textContent='Recorded unit cost R'+total.toFixed(2)+' · Suggested price R'+price.toFixed(2)+' · Unit contribution R'+(price-total).toFixed(2)+'. '+instructions;};form.addEventListener('reset',()=>{result.textContent=instructions;});form.addEventListener('input',e=>{if(costs.includes(e.target.name)||e.target.name==='price')result.textContent='Cost or price changed. Calculate again or review your manual price before saving.';});margin.addEventListener('input',()=>{result.textContent='Target margin changed. Calculate again before using the suggestion.';});})();
